window.kbPageData["views/entry/k-605159868e5cfda1"] = {"key":"entry/k-605159868e5cfda1","state":{"route":"entry/k-605159868e5cfda1"},"node":{"id":"k-605159868e5cfda1","mode":"k","title":"相同年份跨度下的年均增长率比较","type":"原理与机制","domain":"统计","reading":"","intro":"","priority":100,"aliases":["年份跨度相同时，年均增长率随期末量与基期量之比增大而增大"],"qs":["国考 2023 副省级 行测#124"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"directorySummary":"基期量和期末量均为正时，跨 n 年的年均增长率等于期末量与基期量之比开 n 次方后减 1。年份跨度相同，期末量与基期量之比越大，年均增长率越高。","review":{"definition":"基期量和期末量均为正时，跨 n 年的年均增长率等于期末量与基期量之比开 n 次方后减 1。年份跨度相同，期末量与基期量之比越大，年均增长率越高。","explanation":"对正数开相同次数的方再减 1，会保持原有的大小顺序。第124题以2016年为基期、2021年为期末，四地均跨5年。甘肃、浙江、广东、上海的期末量与基期量之比分别约为3.26、3.11、2.46、1.53，因此年均增速从高到低为①④②③，对应C项。","references":[],"evidence":"当年份差n相同时","disposition":"独立词条","basis":"据原题和解析编释。"}},"questions":{"国考 2023 副省级 行测#124":{"paper":"国考 2023 副省级 行测","n":124,"mod":"资料分析","src":["503793642e845de9795f.pdf",25],"asrc":["ecade1ff5af69283232e.pdf",39],"card":"517e66933217fe84bb5c8988","links":[{"id":"k-605159868e5cfda1","role":"解题依据","why":"年均增长率由期末量与基期量之比开同次方后减一得到，该变换保持大小顺序。"}]}},"terms":{},"references":{},"topics":[],"units":{"k-605159868e5cfda1":[["国考 2023 副省级 行测#124"]]}};
